const b = $input.first().json.body || {};
return [{
  json: {
    accion: String(b.accion || '').trim().toLowerCase(),
    token: String(b.token || '').trim(),
    evento_id: String(b.evento_id || '').trim().toUpperCase(),
    inscripcion_id: String(b.inscripcion_id || '').trim().toUpperCase(),
    nombre_acreditacion: String(b.nombre_acreditacion ?? '').trim().replace(/\s+/g, ' ').slice(0, 60),
    observaciones: String(b.observaciones ?? '').trim().slice(0, 200),
    _trae_nombre: b.nombre_acreditacion !== undefined,
    _trae_obs: b.observaciones !== undefined,
  },
}];

const r = $input.first().json;
const mensajes = {
  NO_EXISTE: 'Necesitas iniciar sesión.',
  CERRADA: 'Tu sesión fue cerrada. Vuelve a ingresar.',
  EXPIRADA: 'Tu sesión expiró. Vuelve a ingresar.',
  USUARIO_INACTIVO: 'Tu cuenta está desactivada.',
};
return [{
  json: {
    status: 401,
    body: { ok: false, error: 'SESION_' + (r.motivo || 'INVALIDA'), mensaje: mensajes[r.motivo] || 'Sesión no válida.' },
  },
}];

const d = $('Normalizar solicitud').first().json;
const usuarioId = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const no = (status, codigo, mensaje) => [{ json: { ok: false, error_status: status, error_codigo: codigo, error_mensaje: mensaje } }];

const u = $('Leer usuario').all().map(i => i.json).find(x => x.usuario_id === usuarioId);
if (!u || u.estado !== 'ACTIVO') return no(403, 'USUARIO_INACTIVO', 'Tu cuenta no está activa.');

// Telegram es obligatorio: por ahi llegan siempre las confirmaciones y recordatorios
const tg = $('Leer vinculación Telegram').all().map(i => i.json).find(v => v.usuario_id === usuarioId && v.estado === 'ACTIVA');
if (!tg) return no(403, 'TELEGRAM_NO_VINCULADO', 'Primero vincula tu Telegram desde tu perfil, así te llegan los avisos.');

if (!d.evento_id) return no(400, 'DATOS_INCOMPLETOS', 'Falta el evento.');
const ev = $('Leer evento').all().map(i => i.json).find(e => e.evento_id === d.evento_id);
if (!ev) return no(404, 'EVENTO_NO_EXISTE', 'Ese evento no existe.');
if (ev.estado !== 'PUBLICADO') return no(409, 'EVENTO_NO_DISPONIBLE', 'Este evento no está recibiendo inscripciones.');
const inicio = new Date(`${ev.fecha}T${ev.hora || '00:00'}:00-05:00`).getTime();
if (inicio <= Date.now()) return no(409, 'EVENTO_PASADO', 'Este evento ya empezó o ya pasó.');

const todas = ($input.first().json.inscripciones || []).filter(i => i.inscripcion_id);
const delEvento = todas.filter(i => i.evento_id === ev.evento_id);

// idempotencia: usuario_id + evento_id no puede tener dos inscripciones activas
const activa = delEvento.find(i => i.usuario_id === usuarioId && i.estado !== 'CANCELADA');
if (activa) {
  const txt = ['CONFIRMADA', 'ASISTIO'].includes(activa.estado) ? 'ya tienes cupo confirmado' : 'ya estás en la lista de espera';
  return no(409, 'INSCRIPCION_DUPLICADA', `No te preocupes, ${txt} para este evento.`);
}

const confirmados = delEvento.filter(i => ['CONFIRMADA', 'ASISTIO'].includes(i.estado)).length; // ASISTIO tambien ocupa cupo
const enEspera = delEvento.filter(i => i.estado === 'LISTA_ESPERA').length;
const hayCupo = confirmados < Number(ev.capacidad);
const ahora = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';

return [{
  json: {
    ok: true,
    _evento: { nombre: ev.nombre, fecha: ev.fecha, hora: ev.hora, lugar: ev.lugar },
    inscripcion_id: 'INS-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 4).toUpperCase(),
    usuario_id: usuarioId,
    evento_id: ev.evento_id,
    estado: hayCupo ? 'CONFIRMADA' : 'LISTA_ESPERA',
    fecha_inscripcion: ahora,
    fecha_actualizacion: ahora,
    nombre_acreditacion: d.nombre_acreditacion || u.nombre,
    observaciones: d.observaciones,
    origen: 'WEB',
    orden_espera: hayCupo ? '' : enEspera + 1,
  },
}];

const i = $('Reglas de inscripción').first().json;
return [{
  json: {
    auditoria_id: 'AUD-' + Date.now().toString(36).toUpperCase(),
    inscripcion_id: i.inscripcion_id, usuario_id: i.usuario_id, evento_id: i.evento_id,
    accion: 'CREAR', estado_anterior: '', estado_nuevo: i.estado, fecha: i.fecha_inscripcion,
    resultado: 'OK', detalle: i.estado === 'CONFIRMADA' ? 'Había cupo' : `Sin cupo, puesto ${i.orden_espera} en espera`,
  },
}];

const i = $('Reglas de inscripción').first().json;
const { _evento, ok, ...inscripcion } = i;
return [{
  json: {
    status: 201,
    body: {
      ok: true,
      mensaje: i.estado === 'CONFIRMADA' ? 'Inscripción confirmada.' : 'Quedaste en lista de espera.',
      inscripcion,
    },
  },
}];

const i = $('Reglas de inscripción').first().json;
const e = i._evento;
const confirmada = i.estado === 'CONFIRMADA';
return [{
  json: {
    usuario_id: i.usuario_id, evento_id: i.evento_id, inscripcion_id: i.inscripcion_id,
    tipo: confirmada ? 'INSCRIPCION_CONFIRMADA' : 'INGRESO_LISTA_ESPERA',
    titulo: confirmada ? `Cupo confirmado: ${e.nombre}` : `Estás en lista de espera: ${e.nombre}`,
    mensaje: confirmada
      ? `Tu cupo para "${e.nombre}" está confirmado. Te esperamos el ${e.fecha} a las ${e.hora} en ${e.lugar}.`
      : `El evento "${e.nombre}" está lleno. Quedaste en el puesto ${i.orden_espera} de la lista de espera; si se libera un cupo te lo asignamos automáticamente y te avisamos.`,
  },
}];

const usuarioId = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const todas = $('Leer inscripciones (mis)').all().map(i => i.json).filter(i => i.inscripcion_id);
const eventos = $('Leer eventos (mis)').all().map(i => i.json);

const lista = todas.filter(i => i.usuario_id === usuarioId).map(i => {
  const e = eventos.find(x => x.evento_id === i.evento_id) || {};
  let posicion = null;
  if (i.estado === 'LISTA_ESPERA') {
    // mismo orden que usa WF07: fecha_inscripcion ascendente
    const espera = todas.filter(x => x.evento_id === i.evento_id && x.estado === 'LISTA_ESPERA')
      .sort((a, b) => String(a.fecha_inscripcion).localeCompare(String(b.fecha_inscripcion)));
    posicion = espera.findIndex(x => x.inscripcion_id === i.inscripcion_id) + 1;
  }
  return {
    inscripcion_id: i.inscripcion_id, evento_id: i.evento_id, estado: i.estado,
    fecha_inscripcion: i.fecha_inscripcion, nombre_acreditacion: i.nombre_acreditacion,
    observaciones: i.observaciones, posicion_espera: posicion,
    evento: { nombre: e.nombre, fecha: e.fecha, hora: e.hora, lugar: e.lugar, estado: e.estado, categoria: e.categoria },
  };
}).sort((a, b) => String(b.fecha_inscripcion).localeCompare(String(a.fecha_inscripcion)));

return [{ json: { status: 200, body: { ok: true, total: lista.length, inscripciones: lista } } }];

const d = $('Normalizar solicitud').first().json;
const usuarioId = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const i = $('Leer inscripciones (actualizar)').all().map(x => x.json).find(x => x.inscripcion_id === d.inscripcion_id);
const no = (s, c, m) => [{ json: { ok: false, error_status: s, error_codigo: c, error_mensaje: m } }];
if (!i || i.usuario_id !== usuarioId) return no(404, 'NO_ENCONTRADA', 'No encontramos esa inscripción.');
if (i.estado === 'CANCELADA') return no(409, 'INSCRIPCION_CANCELADA', 'No puedes editar una inscripción cancelada.');
if (d._trae_nombre && d.nombre_acreditacion.length < 3) return no(400, 'DATOS_INVALIDOS', 'El nombre para la escarapela debe tener mínimo 3 caracteres.');

const ahora = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
const fila = { inscripcion_id: i.inscripcion_id, fecha_actualizacion: ahora };
if (d._trae_nombre) fila.nombre_acreditacion = d.nombre_acreditacion;
if (d._trae_obs) fila.observaciones = d.observaciones;
return [{ json: { ok: true, ...fila, _usuario_id: i.usuario_id, _evento_id: i.evento_id, _estado: i.estado } }];

const v = $('Validar edición').first().json;
return [{
  json: {
    auditoria_id: 'AUD-' + Date.now().toString(36).toUpperCase(),
    inscripcion_id: v.inscripcion_id, usuario_id: v._usuario_id, evento_id: v._evento_id,
    accion: 'ACTUALIZAR', estado_anterior: v._estado, estado_nuevo: v._estado, fecha: v.fecha_actualizacion,
    resultado: 'OK', detalle: 'Editó datos de acreditación',
  },
}];

const d = $('Normalizar solicitud').first().json;
const usuarioId = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const i = $('Leer inscripciones (cancelar)').all().map(x => x.json).find(x => x.inscripcion_id === d.inscripcion_id);
const no = (s, c, m) => [{ json: { ok: false, error_status: s, error_codigo: c, error_mensaje: m } }];
if (!i || i.usuario_id !== usuarioId) return no(404, 'NO_ENCONTRADA', 'No encontramos esa inscripción.');
if (i.estado === 'CANCELADA') return no(409, 'YA_CANCELADA', 'Esta inscripción ya estaba cancelada.');
if (i.estado === 'ASISTIO') return no(409, 'YA_ASISTIO', 'Ya registraste tu asistencia a este evento, así que la inscripción no se puede cancelar.');
const e = $('Leer evento (cancelar)').all().map(x => x.json).find(x => x.evento_id === i.evento_id) || {};
const ahora = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
return [{
  json: {
    ok: true, inscripcion_id: i.inscripcion_id, estado: 'CANCELADA', fecha_actualizacion: ahora, orden_espera: '',
    _usuario_id: i.usuario_id, _evento_id: i.evento_id, _estado_anterior: i.estado, _evento_nombre: e.nombre || i.evento_id,
  },
}];

const v = $('Validar cancelación').first().json;
return [{
  json: {
    auditoria_id: 'AUD-' + Date.now().toString(36).toUpperCase(),
    inscripcion_id: v.inscripcion_id, usuario_id: v._usuario_id, evento_id: v._evento_id,
    accion: 'CANCELAR', estado_anterior: v._estado_anterior, estado_nuevo: 'CANCELADA', fecha: v.fecha_actualizacion,
    resultado: 'OK', detalle: v._estado_anterior === 'CONFIRMADA' ? 'Se libera un cupo (WF07 lo reasigna)' : 'Sale de la lista de espera',
  },
}];

const v = $('Validar cancelación').first().json;
return [{
  json: {
    usuario_id: v._usuario_id, evento_id: v._evento_id, inscripcion_id: v.inscripcion_id,
    tipo: 'INSCRIPCION_CANCELADA',
    titulo: `Cancelaste tu inscripción: ${v._evento_nombre}`,
    mensaje: `Tu inscripción a "${v._evento_nombre}" quedó cancelada. Si fue un error, puedes volver a inscribirte mientras haya cupo o lista de espera.`,
  },
}];

const yo = $('Validar sesión (WF02)').first().json.usuario;
if (!['SUPERVISOR', 'ADMINISTRADOR'].includes(yo.rol)) {
  return [{ json: { status: 403, body: { ok: false, error: 'SIN_PERMISO', mensaje: 'Solo supervisores y administradores pueden ver los inscritos.' } } }];
}
const esAdmin = yo.rol === 'ADMINISTRADOR';
const ins = $('Leer inscripciones (panel)').all().map(i => i.json).filter(i => i.inscripcion_id);
const usuarios = $('Leer usuarios (panel)').all().map(i => i.json);
// el supervisor ve el correo a medias, el admin lo ve completo
const tapar = (e) => {
  if (esAdmin || !e) return e || '';
  const [u, d] = String(e).split('@');
  return u.slice(0, 2) + '***@' + (d || '');
};
const eventos = $('Leer eventos (panel)').all().map(i => i.json)
  .filter(e => e.evento_id && (esAdmin || e.estado !== 'BORRADOR'))
  .map(e => {
    const del = ins.filter(i => i.evento_id === e.evento_id);
    const espera = del.filter(i => i.estado === 'LISTA_ESPERA')
      .sort((a, b) => String(a.fecha_inscripcion).localeCompare(String(b.fecha_inscripcion)));
    const inscritos = del.map(i => {
      const u = usuarios.find(x => x.usuario_id === i.usuario_id) || {};
      return {
        inscripcion_id: i.inscripcion_id, estado: i.estado, fecha_inscripcion: i.fecha_inscripcion,
        // el admin puede cambiar el rol desde esta misma lista, por eso le llegan id y rol
        ...(esAdmin ? { usuario_id: i.usuario_id, rol: u.rol || 'VECINO' } : {}),
        nombre: u.nombre || i.usuario_id, email: tapar(u.email_normalizado),
        nombre_acreditacion: i.nombre_acreditacion, observaciones: i.observaciones,
        puesto_espera: i.estado === 'LISTA_ESPERA' ? espera.findIndex(x => x.inscripcion_id === i.inscripcion_id) + 1 : null,
      };
    }).sort((a, b) => String(a.fecha_inscripcion).localeCompare(String(b.fecha_inscripcion)));
    return {
      evento_id: e.evento_id, nombre: e.nombre, categoria: e.categoria, fecha: e.fecha, hora: e.hora, lugar: e.lugar,
      estado: e.estado, capacidad: Number(e.capacidad) || 0,
      confirmados: del.filter(i => ['CONFIRMADA', 'ASISTIO'].includes(i.estado)).length,
      en_espera: espera.length,
      canceladas: del.filter(i => i.estado === 'CANCELADA').length,
      inscritos,
    };
  })
  .sort((a, b) => `${a.fecha} ${a.hora}`.localeCompare(`${b.fecha} ${b.hora}`));
return [{ json: { status: 200, body: { ok: true, rol: yo.rol, eventos } } }];

const d = $input.first().json;
return [{
  json: {
    status: d.error_status || 400,
    body: { ok: false, error: d.error_codigo || 'ERROR', mensaje: d.error_mensaje || 'No se pudo procesar la solicitud.' },
  },
}];
